{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-html-ppt-pitch-deck",
  "title": "Write a Demo Day Pitch like a Top Accelerator Partner",
  "title_i18n": {
    "en": "Write a Demo Day Pitch like a Top Accelerator Partner",
    "zh-CN": "像顶级加速器合伙人一样写 Demo Day 路演",
    "zh-TW": "像顶级加速器合伙人一样写 Demo Day 路演"
  },
  "version": "0.1.0",
  "publishedAt": "2026-05-12T07:18:16Z",
  "description": "Open Design's demo-day pitch: hook, traction, moat, and the raise — built to make a partner sit up by page three. Built as a decision-grade fundraising pitch deck for accelerator partners, angels.",
  "description_i18n": {
    "en": "Open Design's demo-day pitch: hook, traction, moat, and the raise — built to make a partner sit up by page three. Built as a decision-grade fundraising pitch deck for accelerator partners, angels.",
    "zh-CN": "像顶级加速器合伙人一样写 Demo Day 路演——一份可商业交付的融资路演 Deck，围绕真实主题、证据链与决策目标组织。",
    "zh-TW": "像顶级加速器合伙人一样写 Demo Day 路演——一份可商业交付的融资路演 Deck，围绕真实主题、证据链与决策目标组织。"
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/html-ppt-pitch-deck",
  "tags": [
    "example",
    "first-party",
    "deck",
    "finance",
    "web",
    "pitch-deck",
    "pitch",
    "fundraising",
    "seed-round",
    "investor-deck",
    "vc-deck",
    "pitch-slides",
    "html-ppt-pitch-deck",
    "fundraising-pitch",
    "series-a-pitch-deck",
    "decision-deck",
    "commercial-slide-agent"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "deck",
    "scenario": "finance",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Create \"Write a Demo Day Pitch like a Top Accelerator Partner\" as a decision-grade Fundraising pitch deck in this template's own visual system. Subject: Open Design's demo-day pitch: hook, traction, moat, and the raise — built to make a partner sit up by page three. Audience: accelerator partners, angels. First ask only for missing essentials: audience, decision target, source-of-truth materials, deadline, and must-keep numbers. Then produce the slide plan, written slides, visual direction, speaker-ready structure, and a critic pass against this rubric: would an investor know why this is venture-scale and urgent.",
        "zh-CN": "像顶级加速器合伙人一样写 Demo Day 路演。像顶级加速器合伙人一样写 Demo Day 路演——一份可商业交付的融资路演 Deck，围绕真实主题、证据链与决策目标组织。 主题：Open Design's demo-day pitch: hook, traction, moat, and the raise — built to make a partner sit up by page three. 先确认受众、决策目标、素材来源、截止时间和必须保留的数据，再输出叙事主线、页面规划、逐页文案、视觉方向和按评审标准自检的版本。"
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Write a Demo Day Pitch like a Top Accelerator Partner",
          "title_i18n": {
            "en": "Write a Demo Day Pitch like a Top Accelerator Partner",
            "zh-CN": "像顶级加速器合伙人一样写 Demo Day 路演",
            "zh-TW": "像顶级加速器合伙人一样写 Demo Day 路演"
          }
        }
      ]
    },
    "inputs": [
      {
        "name": "one_line_pitch",
        "label": "Name + one-line pitch",
        "type": "text",
        "required": true,
        "placeholder": "Company name and one sentence explaining what it does"
      },
      {
        "name": "key_traction_numbers",
        "label": "Key traction numbers",
        "type": "text",
        "required": true,
        "placeholder": "Revenue, growth, users, pilots, retention, pipeline, or other investor proof"
      },
      {
        "name": "ask_and_use_of_funds",
        "label": "Ask + use of funds",
        "type": "text",
        "required": true,
        "placeholder": "Round size and how the capital will be used"
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ],
    "category": "fundraising-pitch"
  }
}
